package com.medtrack.warehouse.entity;
import com.medtrack.shared.model.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="storage_locations") public class StorageLocation extends BaseEntity { @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="warehouse_id",nullable=false) private Warehouse warehouse; @Column(nullable=false) private String zone; @Column(nullable=false) private String rack; @Column(nullable=false) private String shelf; @Column(name="bin_code",nullable=false) private String binCode; protected StorageLocation(){} public StorageLocation(Warehouse wh,String zone,String rack,String shelf,String bin){warehouse=wh;this.zone=zone;this.rack=rack;this.shelf=shelf;binCode=bin;} public Warehouse getWarehouse(){return warehouse;} public String getZone(){return zone;} public String getRack(){return rack;} public String getShelf(){return shelf;} public String getBinCode(){return binCode;} }
